Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('COMPORTAMENTI_ISTANZE','GENERA_PRATICA_SUAP','Gestisce l''attivazione dell''integrazione SUAP/Edilizia mediante canale di protocollazione. Valori attesi ''S'' funzionalità attiva, ''N o null'' funzionalità non attiva');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('COMPORTAMENTI_ISTANZE','GENERA_PRATICA_SUAP_URL','Url del servizio genera pratica SUAP');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('COMPORTAMENTI_ISTANZE','GENERA_PRATICA_SUAP_VALIDA','Valori attesi S o N (NULL) indica se validare o meno lo schema prima di creare il file xml che rappresenta la pratica');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('STC', 'USA_NUMISTANZA_AS_NODI', 'Rappresenta la lista degli idnodi ( separata da virgola ) per i quali attivare il comportamento di usare il numero istanza del sistema mittente (vedi parametro USA_NUMISTANZA_ALTRO_SISTEMA). I valori vanno specificati separati da virgola es: 410,420,430.');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PROTOINF','CODAMM_DESTINATARIO','In questo campo va necessariamente indicato il codice dell''amministrazione del backoffice alla quale saranno inviati i dati come destinatario fisso dei protocolli in partenza. In particolare saranno inviati i dati relativi a: DENOMINAZIONE, PEC, INDIRIZZO, UFFICIO (Codice UO). Da notare che solo la denominazione è obbligatoria.');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PROTOINF','IGNORA_CLASSIFICA','Se valorizzato a 1 ignorerà qualsiasi valore proveniente dalla classifica, il tutto in quanto tale voce non è obbligatoria nel sistema di protocollo mentre lo è in VBG.');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PROTOINF','NETWORK_DOMAIN','Indicare la credenziale di dominio per l''accesso in modalità share di rete utile per il passaggio dei file nel percorso indicato nel parametro BASEPATH_FILES_LOCAL');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PROTOINF','NETWORK_PASSWORD','Indicare la credenziale di password per l''accesso in modalità share di rete utile per il passaggio dei file nel percorso indicato nel parametro BASEPATH_FILES_LOCAL');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PROTOINF','NETWORK_USERNAME','Indicare la credenziale di username per l''accesso in modalità share di rete utile per il passaggio dei file nel percorso indicato nel parametro BASEPATH_FILES_LOCAL');
Insert into VERTICALIZZAZIONIPARAMETRIBASE (MODULO,PARAMETRO,DESCRIZIONE) values ('PROTOCOLLO_PROTOINF','PROPRIETARIO','Indicare il codice del proprietario del protocollo esposto su PROTOINF, il valore è da recuperare dalla tabella PI_PERSONA campo PI_PE_PERSONA');
